<?php
declare(strict_types=1);
function people_schema(PDO $db): void {
 $db->exec("CREATE TABLE IF NOT EXISTS people_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);CREATE TABLE IF NOT EXISTS work_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,username TEXT NOT NULL,token TEXT UNIQUE NOT NULL,started INTEGER NOT NULL,seen INTEGER NOT NULL,ended INTEGER,reason TEXT NOT NULL DEFAULT '',approved INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS work_activity(session_id INTEGER NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(session_id,at));CREATE INDEX IF NOT EXISTS work_sessions_user ON work_sessions(user_id,started);CREATE TABLE IF NOT EXISTS work_adjustments(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,started INTEGER NOT NULL,ended INTEGER NOT NULL,approved INTEGER NOT NULL,note TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS people_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,username TEXT NOT NULL,display_name TEXT NOT NULL,event TEXT NOT NULL,target TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS people_audit_date ON people_audit(created_at,id)");
}
function people_require_owner(): void {if(!(team_identity()['owner']??false))throw new RuntimeException('Chỉ quản trị viên gốc được thực hiện thao tác này.',403);}
function people_name($v): string {if(!is_string($v)||mb_strlen($v)>100||preg_match('/[\p{C}]/u',$v))throw new RuntimeException('Tên hiển thị tối đa 100 ký tự, không chứa ký tự điều khiển.',400);return trim($v);}
function people_profile_complete(array $u): bool {foreach(['full_name','name','phone','birth_date','address'] as $key)if(trim((string)($u[$key]??''))==='')return false;return true;}
function people_profile_get(?array $u=null): array {$u??=team_identity();if($u['owner'])return ['name'=>$u['name']]+people_setting('owner_profile',[]);$q=team_db()->prepare('SELECT name,full_name,phone,birth_date,address,profile_edits FROM staff WHERE id=?');$q->execute([$u['id']]);return $q->fetch()?:[];}
function people_validate_profile(array $data,bool $required=true): array {
 $full=people_name($data['full_name']??'');$phone=preg_replace('/[\s().-]+/u','',trim((string)($data['phone']??'')));$birth=(string)($data['birth_date']??'');$address=trim((string)($data['address']??''));if($required&&($full===''||$phone===''||$birth===''||$address===''))throw new RuntimeException('Vui lòng điền đủ họ tên, tên hiển thị, số điện thoại, ngày sinh và địa chỉ.',400);
 if($phone!==''&&!preg_match('/^(?:0[0-9]{9}|\+84[0-9]{9})$/D',$phone))throw new RuntimeException('Số điện thoại cần 10 chữ số bắt đầu bằng 0 hoặc dạng +84.',400);
 if($birth!==''){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$birth,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d')!==$birth||$birth<'1900-01-01'||$d>new DateTimeImmutable('today',new DateTimeZone('Asia/Ho_Chi_Minh')))throw new RuntimeException('Ngày sinh không hợp lệ.',400);}
 if(mb_strlen($address)>1000||preg_match('/[\p{C}]/u',str_replace(["\r","\n"],'',$address)))throw new RuntimeException('Địa chỉ tối đa 1.000 ký tự.',400);return ['full_name'=>$full,'phone'=>$phone,'birth_date'=>$birth,'address'=>$address];
}
function people_onboarding_guard(): void {
 $u=team_identity();if(!$u||$u['owner']||$u['profileComplete'])return;$script=basename($_SERVER['SCRIPT_NAME']??'');if(in_array($script,['people.php','people-api.php','notifications.php','password.php'],true)||($script==='index.php'&&($_SERVER['REQUEST_METHOD']??'')==='POST'&&($_POST['action']??'')==='logout'))return;
 if(str_ends_with($script,'api.php')){http_response_code(403);header('Content-Type: application/json; charset=utf-8');echo json_encode(['error'=>'Cần hoàn thiện hồ sơ cá nhân trước khi làm việc.','profileRequired'=>true]);exit;}header('Location: /quan-tri/people.php?onboarding=1');exit;
}
function people_audit(string $event,string $target,array $details=[],?PDO $db=null,?array $actor=null): void {
 $db??=team_db();people_schema($db);$actor??=team_identity()??['id'=>0,'username'=>'system','name'=>'Hệ thống'];
 $db->prepare('INSERT INTO people_audit(user_id,username,display_name,event,target,details,created_at) VALUES(?,?,?,?,?,?,?)')->execute([(int)$actor['id'],$actor['username'],$actor['name']?:$actor['username'],$event,$target,json_encode($details,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),gmdate('Y-m-d\TH:i:s\Z')]);
}
function people_setting(string $key,$default=null){$db=team_db();people_schema($db);$q=$db->prepare('SELECT value FROM people_settings WHERE key=?');$q->execute([$key]);$v=$q->fetchColumn();return $v===false?$default:json_decode($v,true,512,JSON_THROW_ON_ERROR);}
function people_set(string $key,$value): void {$db=team_db();people_schema($db);$db->prepare('INSERT INTO people_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value')->execute([$key,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);}
function people_profile_save(array $data): array {
 $u=team_identity();if(!$u)throw new RuntimeException('Vui lòng đăng nhập.',401);$name=people_name($data['name']??'');$before=people_profile_get($u);$profile=people_validate_profile($data,!$u['owner']);if(!$u['owner']&&$name==='')throw new RuntimeException('Cần điền tên hiển thị.',400);$changed=array_diff_assoc($profile+['name'=>$name],array_intersect_key($before,$profile+['name'=>$name]));$countEdit=!$u['owner']&&$u['profileComplete']&&count($changed)>0;if($countEdit&&(int)($before['profile_edits']??0)>=2)throw new RuntimeException('Bạn đã dùng đủ 2 lượt sửa hồ sơ. Liên hệ quản trị viên để điều chỉnh.',403);$db=team_db();$db->beginTransaction();try{if($countEdit){$q=$db->prepare('UPDATE staff SET profile_edits=profile_edits+1 WHERE id=? AND profile_edits<2');$q->execute([$u['id']]);if(!$q->rowCount())throw new RuntimeException('Bạn đã dùng đủ 2 lượt sửa hồ sơ.',403);}if($u['owner']){people_set('owner_name',$name);people_set('owner_profile',$profile);}else $db->prepare('UPDATE staff SET name=?,full_name=?,phone=?,birth_date=?,address=? WHERE id=?')->execute([$name,$profile['full_name'],$profile['phone'],$profile['birth_date'],$profile['address'],$u['id']]);people_audit('profile','Hồ sơ cá nhân',['before'=>$before,'after'=>array_merge($profile,['name'=>$name])]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}return team_identity();
}
function people_session_start(?int $now=null): void {
 $u=team_identity();if(!$u)return;if($u['owner']){unset($_SESSION['work_token']);people_audit('login','Đăng nhập',[],null,$u);return;}$db=team_db();people_schema($db);$now??=time();$token=bin2hex(random_bytes(24));$db->beginTransaction();try{$db->prepare('INSERT INTO work_sessions(user_id,username,token,started,seen) VALUES(?,?,?,?,?)')->execute([$u['id'],$u['username'],$token,$now,$now]);$db->prepare('INSERT INTO work_activity(session_id,at) VALUES(?,?)')->execute([(int)$db->lastInsertId(),$now]);people_audit('login','Đăng nhập',[],null,$u);$db->commit();$_SESSION['work_token']=$token;}catch(Throwable $e){$db->rollBack();throw $e;}
}
function people_session_touch(): void {
 if(!admin_logged_in())return;if(team_identity()['owner']){if(!empty($_SESSION['work_token']))people_session_end('owner_exempt');return;}if(empty($_SESSION['work_token']))people_session_start();
}
function people_activity(array $data): void {
 if(team_identity()['owner']??false)return;
 $db=team_db();$q=$db->prepare('SELECT * FROM work_sessions WHERE token=?');$q->execute([$_SESSION['work_token']??'']);$s=$q->fetch();if(!$s)return;$now=time();$at=$data['at']??null;if(!is_int($at)||$at>$now+5||$at<$now-90)throw new RuntimeException('Thời điểm hoạt động không hợp lệ.',400);$at=min($at,$now);if($at<=(int)$s['seen'])return;if($s['ended']!==null){people_session_start($at);return;}$db->beginTransaction();try{$db->prepare('UPDATE work_sessions SET seen=? WHERE id=? AND ended IS NULL')->execute([$at,$s['id']]);$db->prepare('INSERT OR IGNORE INTO work_activity(session_id,at) VALUES(?,?)')->execute([$s['id'],$at]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}
function people_session_end(string $reason='logout',?int $end=null): void {
 if(empty($_SESSION['work_token'])){if(team_identity()['owner']??false)people_audit($reason==='logout'?'logout':'session_end','Phiên quản trị viên',['reason'=>$reason]);return;}$db=team_db();people_schema($db);$q=$db->prepare('SELECT * FROM work_sessions WHERE token=? AND ended IS NULL');$q->execute([$_SESSION['work_token']]);$row=$q->fetch();if(!$row)return;if($reason!=='logout')$end=(int)$row['seen'];$end=max((int)$row['started'],$end??time());$u=team_identity()??['id'=>(int)$row['user_id'],'username'=>$row['username'],'name'=>$row['username']];
 $db->beginTransaction();try{$db->prepare('UPDATE work_sessions SET ended=?,seen=?,reason=?,approved=? WHERE id=? AND ended IS NULL')->execute([$end,$end,$reason,in_array($reason,['logout','idle','expired'],true)?1:0,$row['id']]);$db->prepare('INSERT OR IGNORE INTO work_activity(session_id,at) VALUES(?,?)')->execute([$row['id'],$end]);people_audit($reason==='logout'?'logout':'session_end','Phiên #'.$row['id'],['reason'=>$reason,'started'=>(int)$row['started'],'ended'=>$end],null,$u);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}unset($_SESSION['work_token']);
}
function people_effective_sessions(int $id,int $from,int $to): array {
 if($id===0)return [];
 $db=team_db();people_schema($db);$q=$db->prepare('SELECT s.*,a.started AS adjusted_start,a.ended AS adjusted_end,a.approved AS adjusted_approved,a.note AS adjustment_note,a.actor AS adjustment_actor FROM work_sessions s LEFT JOIN work_adjustments a ON a.id=(SELECT max(b.id) FROM work_adjustments b WHERE b.session_id=s.id) WHERE s.user_id=? AND COALESCE(a.started,s.started)<? AND (COALESCE(a.ended,s.ended) IS NULL OR COALESCE(a.ended,s.ended)>?) ORDER BY COALESCE(a.started,s.started)');$q->execute([$id,$to,$from]);$rows=$q->fetchAll();$activity=$db->prepare('SELECT at FROM work_activity WHERE session_id=? ORDER BY at');foreach($rows as &$r){unset($r['token']);$r['effective_start']=(int)($r['adjusted_start']??$r['started']);$r['effective_end']=$r['adjusted_end']??$r['ended'];$r['effective_approved']=(int)($r['adjusted_approved']??$r['approved']);if($r['effective_end']===null){$r['effective_end']=(int)$r['seen'];$r['effective_approved']=1;$r['provisional']=true;}$activity->execute([$r['id']]);$r['activity']=array_map('intval',$activity->fetchAll(PDO::FETCH_COLUMN));$r['effective_end']=$r['effective_end']===null?null:(int)$r['effective_end'];}return $rows;
}
function people_adjust(array $data): void {
 people_require_owner();$id=filter_var($data['id']??null,FILTER_VALIDATE_INT);$start=people_local_time($data['started']??'');$end=people_local_time($data['ended']??'');$note=trim((string)($data['note']??''));$approved=$data['approved']??null;if(!$id||$end<=$start||$end-$start>48*3600||mb_strlen($note)<3||mb_strlen($note)>1000||!is_bool($approved))throw new RuntimeException('Cần thời gian hợp lệ (tối đa 48 giờ), lý do và trạng thái duyệt.',400);
 $db=team_db();$q=$db->prepare('SELECT * FROM work_sessions WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Không tìm thấy phiên làm việc.',404);if((int)$old['user_id']===0)throw new RuntimeException('Quản trị viên không thuộc bảng chấm công.',403);if($old['ended']===null&&time()-(int)$old['seen']<=60)throw new RuntimeException('Phiên vẫn đang mở. Nhân viên cần đăng xuất trước khi duyệt.',409);
 $db->beginTransaction();try{$db->prepare('INSERT INTO work_adjustments(session_id,started,ended,approved,note,actor,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$id,$start,$end,$approved?1:0,$note,team_identity()['username'],gmdate('c')]);people_audit('attendance_adjust','Phiên #'.$id,['before'=>array_diff_key($old,['token'=>true]),'started'=>$start,'ended'=>$end,'approved'=>$approved,'note'=>$note]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}
function people_local_time($s): int {if(!is_string($s))throw new RuntimeException('Thời gian không hợp lệ.',400);$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$s,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d\TH:i')!==$s||$d->getTimestamp()>time()+60)throw new RuntimeException('Thời gian cần đúng định dạng và không ở tương lai.',400);return $d->getTimestamp();}
function people_month($s): array {if(!is_string($s)||!preg_match('/^20[0-9]{2}-(0[1-9]|1[0-2])$/D',$s))throw new RuntimeException('Tháng không hợp lệ.',400);$a=new DateTimeImmutable($s.'-01',new DateTimeZone('Asia/Ho_Chi_Minh'));return [$a->getTimestamp(),$a->modify('+1 month')->getTimestamp()];}
function people_audit_list(array $input): array {
 people_require_owner();$page=max(1,(int)($input['page']??1));$limit=50;$where=[];$args=[];
 foreach(['username','event'] as $key)if(($input[$key]??'')!==''){$where[]=$key.'=?';$args[]=(string)$input[$key];}
 foreach(['from','to'] as $key)if(($input[$key]??'')!==''){$s=(string)$input[$key];$d=DateTimeImmutable::createFromFormat('!Y-m-d',$s,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d')!==$s)throw new RuntimeException('Ngày lọc không hợp lệ.',400);if($key==='to')$d=$d->modify('+1 day');$where[]='created_at'.($key==='from'?'>=':'<').'?';$args[]=$d->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');}
 $a=team_db();people_schema($a);if(!in_array('order_audit',array_column($a->query('PRAGMA database_list')->fetchAll(),'name'),true))$a->exec("ATTACH DATABASE ".$a->quote(admin_private().'/orders.sqlite')." AS order_audit");$b=admin_db();people_schema($b);$sql=' FROM (SELECT *,\'auth\' AS source FROM main.people_audit UNION ALL SELECT *,\'orders\' AS source FROM order_audit.people_audit)'.($where?' WHERE '.implode(' AND ',$where):'');$q=$a->prepare('SELECT count(*)'.$sql);$q->execute($args);$total=(int)$q->fetchColumn();$q->closeCursor();$page=min($page,max(1,(int)ceil($total/$limit)));$q=$a->prepare('SELECT id,user_id,username,display_name,event,target,created_at,source'.$sql.' ORDER BY created_at DESC,source,id DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$q->execute($args);$rows=$q->fetchAll();$q->closeCursor();return ['rows'=>$rows,'total'=>$total,'page'=>$page,'pages'=>max(1,(int)ceil($total/$limit))];
}
function people_cell(array $cell): array {unset($cell['custom']);if(!empty($cell['f']))unset($cell['v']);return $cell;}
function people_workbook_diff(?array $before,array $after): array {
 $changes=[];$before??=['sheets'=>[]];foreach(array_unique(array_merge(array_keys($before['sheets']??[]),array_keys($after['sheets']??[]))) as $id){$old=$before['sheets'][$id]??[];$new=$after['sheets'][$id]??[];$label=$new['name']??$old['name']??$id;
 if(!$old||!$new)$changes[]=['sheet'=>$label,'field'=>'Trang tính','before'=>$old?'Tồn tại':null,'after'=>$new?'Tồn tại':null];
 foreach(array_unique(array_merge(array_keys($old['cellData']??[]),array_keys($new['cellData']??[]))) as $r)foreach(array_unique(array_merge(array_keys($old['cellData'][$r]??[]),array_keys($new['cellData'][$r]??[]))) as $c){$a=people_cell($old['cellData'][$r][$c]??[]);$b=people_cell($new['cellData'][$r][$c]??[]);if($a!=$b){$col='';for($i=(int)$c+1;$i>0;$i=intdiv($i-1,26))$col=chr(65+($i-1)%26).$col;$changes[]=['sheet'=>$label,'cell'=>$col.((int)$r+1),'before'=>$a,'after'=>$b];}}
 unset($old['cellData'],$new['cellData']);foreach(array_unique(array_merge(array_keys($old),array_keys($new))) as $key)if(($old[$key]??null)!=($new[$key]??null))$changes[]=['sheet'=>$label,'field'=>$key,'before'=>$old[$key]??null,'after'=>$new[$key]??null];}
 foreach(array_unique(array_merge(array_keys($before),array_keys($after))) as $key)if($key!=='sheets'&&($before[$key]??null)!=($after[$key]??null))$changes[]=['field'=>$key,'before'=>$before[$key]??null,'after'=>$after[$key]??null];return $changes;
}

function people_audit_detail(array $input): array {people_require_owner();$db=($input['source']??'')==='orders'?admin_db():team_db();people_schema($db);$q=$db->prepare('SELECT details FROM people_audit WHERE id=?');$q->execute([(int)($input['id']??0)]);$raw=$q->fetchColumn();if($raw===false)throw new RuntimeException('Không tìm thấy nhật ký.',404);return json_decode($raw,true,512,JSON_THROW_ON_ERROR);}
